const existing = $('Read Existing Ideas').all()
  .map(i => i.json['Video ID']).filter(Boolean);
let max = 0;
for (const id of existing) {
  const n = parseInt(String(id).replace('VID-', ''), 10);
  if (!isNaN(n) && n > max) max = n;
}

const ideas = $input.first().json.output.ideas;
const today = $now.toFormat('yyyy-MM-dd');
const rank = { High: 3, Medium: 2, Low: 1 };
let best = 0;
ideas.forEach((idea, i) => {
  if ((rank[idea.priority] || 0) > (rank[ideas[best].priority] || 0)) best = i;
});

return ideas.map((idea, i) => ({
  json: {
    'Video ID': `VID-${String(max + i + 1).padStart(3, '0')}`,
    'Topic': idea.topic,
    'Title': idea.title,
    'Category': idea.category,
    'Target Audience': idea.target_audience,
    'Status': i === best ? 'Selected' : 'Idea',
    'Priority': idea.priority,
    'Date Added': today,
    'Explanation': idea.explanation
  }
}));

const idea = $('Pick Selected Idea').first().json;
const out = $input.first().json.output;
const bullets = (arr) => Array.isArray(arr) ? arr.map(x => '• ' + x).join('\n') : String(arr || '');

return [{ json: {
  'Video ID': idea['Video ID'],
  'Title': idea['Title'],
  'Learning Goal': out.learning_goal,
  'Main Points': bullets(out.main_points),
  'Viewer Questions': bullets(out.viewer_questions),
  'Intro': out.intro,
  'Main Content': out.main_content,
  'Examples': bullets(out.examples),
  'Conclusion': out.conclusion,
  'To Verify': bullets(out.verify_before_publishing),
  'Status': 'Researched',
  'Date Created': $now.toFormat('yyyy-MM-dd')
}}];

parameters.text:
=You are a scriptwriter for a fictional beginner-focused YouTube channel called "Beginner AI Lab".
Tone: friendly, simple, practical and jargon-free. Write for students and beginners with no technical background.

Write a complete YouTube script for this video.

Title: {{ $json['Title'] }}
Category: {{ $json['Category'] }}
Target audience: {{ $json['Target Audience'] }}

RESEARCH PLAN (use only this material):
Learning goal: {{ $json.research['Learning Goal'] }}
Main points: {{ $json.research['Main Points'] }}
Viewer questions: {{ $json.research['Viewer Questions'] }}
Intro idea: {{ $json.research['Intro'] }}
Main content plan: {{ $json.research['Main Content'] }}
Examples: {{ $json.research['Examples'] }}
Conclusion idea: {{ $json.research['Conclusion'] }}
Items to verify: {{ $json.research['To Verify'] }}

Write:
- hook: an interesting opening (2 to 4 sentences) that explains why viewers should keep watching
- script: the full spoken script, in this order:
  1. HOOK
  2. MAIN CONTENT, divided into clearly labelled sections (SECTION 1, SECTION 2 ...) covering the main points, with a simple example where useful
  3. CONCLUSION: short recap
  4. CALL TO ACTION
- call_to_action: one natural sentence asking viewers to subscribe or watch another video

Rules:
- Use short, simple sentences that are easy to say out loud.
- Use ONLY information from the research plan. Do not invent statistics, prices, product features or claims.
- For anything listed under "Items to verify", do not state it as fact. Write [VERIFY: short note] instead.
- Do not use real logos, real channel names or copyrighted content.
- Aim for about 400 to 600 words.

Return only the structured data.

parameters.jsCode:
const idea = $('Pick Selected Idea').first().json;
const out = $input.first().json.output;
const script = out.script || '';

return [{ json: {
  'Video ID': idea['Video ID'],
  'Title': idea['Title'],
  'Hook': out.hook,
  'Script': script,
  'Call To Action': out.call_to_action,
  'Word Count': script.trim().split(/\s+/).length,
  'Status': 'Script Ready',
  'Date Created': $now.toFormat('yyyy-MM-dd')
}}];

const idea = $('Pick Selected Idea').first().json;
const research = $('Format Research Rows').first().json;
return [{ json: { ...idea, research } }];

const src = $('Format Script Rows').first().json;
const out = $input.first().json.output;
const WPM = 150;

const fmt = (secs) => {
  const m = Math.floor(secs / 60);
  const s = Math.round(secs % 60);
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
};
const sectionWords = (script) => {
  const header = /^(HOOK|SECTION\s*\d+.*|CONCLUSION|CALL TO ACTION)\s*$/i;
  const sections = [];
  for (const line of String(script).split('\n')) {
    if (header.test(line.trim())) { sections.push(0); continue; }
    if (sections.length) sections[sections.length - 1] += line.trim().split(/\s+/).filter(Boolean).length;
  }
  return sections;
};

const chapters = out.chapters || [];
let words = sectionWords(src['Script']);
if (words.length !== chapters.length) {
  const total = String(src['Script']).trim().split(/\s+/).length;
  words = chapters.map(() => total / Math.max(chapters.length, 1));
}
let secs = 0;
const chapterLines = chapters.map((title, idx) => {
  const line = `${fmt(secs)} ${title}`;
  secs += (words[idx] / WPM) * 60;
  return line;
});

return [{ json: {
  'Video ID': src['Video ID'],
  'Original Title': src['Title'],
  'Title Options': (out.title_options || []).map((t, n) => `${n + 1}. ${t}`).join('\n'),
  'Recommended Title': out.recommended_title,
  'Title Reason': out.title_reason,
  'Description': out.description,
  'Tags': (out.tags || []).join(', '),
  'Summary': out.summary,
  'Chapters': chapterLines.join('\n') + '\n(estimated timestamps)',
  'Status': 'Publishing Data Ready',
  'Date Created': $now.toFormat('yyyy-MM-dd')
}}];

const v = $('Prepare Thumbnail Input').first().json;
const out = $input.first().json.output;
const bullets = (arr) => Array.isArray(arr) ? arr.map(x => '• ' + x).join('\n') : String(arr || '');

return [{ json: {
  'Video ID': v['Video ID'],
  'Title': v['Recommended Title'],
  'Concept': out.concept,
  'Thumbnail Text': String(out.thumbnail_text || '').toUpperCase(),
  'Visual Description': out.visual_description,
  'Image Prompt': out.image_prompt,
  'Visual Assets Needed': bullets(out.visual_assets_needed),
  'Thumbnail Status': 'Concept Ready',
  'Date Created': $now.toFormat('yyyy-MM-dd')
}}];

const t = $('Format Thumbnail Rows').first().json;
const s = $('Format Script Rows').first().json;

return [{ json: {
  'Video ID': t['Video ID'],
  'Title': s['Title'],
  'Script Status': 'Script Ready',
  'Thumbnail Status': 'Concept Ready',
  'Video Status': 'Production',
  'Publish Date': $now.plus({ days: 3 }).toFormat('yyyy-MM-dd'),
  'Notes': 'Pipeline run ' + $now.toFormat('yyyy-MM-dd HH:mm') + ': script ready, thumbnail concept ready, in production (fictional publish date)'
}}];

const id = $('Build Calendar Row').first().json['Video ID'];
const rnd = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;

const views = rnd(3000, 20000);
const likes = Math.round(views * rnd(40, 110) / 1000);
const comments = Math.round(views * rnd(5, 25) / 1000);
const watchHours = Math.round(views * (rnd(20, 45) / 10) / 60);
const ctr = rnd(30, 85) / 10;
const subs = Math.round(views * rnd(5, 20) / 1000);

return [{ json: {
  'Video ID': id,
  'Views': views,
  'Likes': likes,
  'Comments': comments,
  'Watch Time': watchHours,
  'CTR': ctr,
  'Date': $now.toFormat('yyyy-MM-dd'),
  'Subscribers Gained': subs
}}];

const id = $('Simulate Publish and Metrics').first().json['Video ID'];
return [{ json: {
  'Video ID': id,
  'Video Status': 'Published',
  'Publish Date': $now.toFormat('yyyy-MM-dd'),
  'Notes': 'Simulated publish (fictional). Test data only.'
}}];

const num = v => parseFloat(String(v ?? '').replace(/[%,\s]/g, '')) || 0;
const round = (n, d = 2) => Math.round(n * 10 ** d) / 10 ** d;

const perf = $('Read Video Performance').all().map(i => i.json).filter(r => r['Video ID']);
const ideas = $('Read Video Ideas').all().map(i => i.json);

const info = {};
for (const r of ideas) info[r['Video ID']] = r;

const videos = perf.map(r => {
  const views = num(r['Views']), likes = num(r['Likes']), comments = num(r['Comments']);
  const hours = num(r['Watch Time']), subs = num(r['Subscribers Gained']);
  const meta = info[r['Video ID']] || {};
  return {
    video_id: r['Video ID'],
    title: meta['Title'] || 'Unknown title',
    topic: meta['Topic'] || 'Unknown',
    category: meta['Category'] || 'Unknown',
    views, likes, comments,
    watch_hours: hours,
    ctr_percent: num(r['CTR']),
    subscribers_gained: subs,
    engagement_rate: views ? round((likes + comments) / views * 100) : 0,
    avg_minutes_watched_per_view: views ? round(hours * 60 / views) : 0,
    subs_per_1000_views: views ? round(subs / views * 1000) : 0
  };
});

const sum = (list, k) => list.reduce((s, v) => s + v[k], 0);

const group = key => {
  const g = {};
  for (const v of videos) (g[v[key]] = g[v[key]] || []).push(v);
  return Object.entries(g).map(([name, list]) => ({
    name,
    videos: list.length,
    avg_views: round(sum(list, 'views') / list.length, 0),
    avg_engagement_rate: round(sum(list, 'engagement_rate') / list.length),
    avg_ctr_percent: round(sum(list, 'ctr_percent') / list.length),
    low_sample: list.length < 2
  })).sort((a, b) => b.avg_engagement_rate - a.avg_engagement_rate);
};

const n = videos.length || 1;
const stats = {
  data_type: 'SIMULATED (fictional test data)',
  overall: {
    videos_analyzed: videos.length,
    total_views: sum(videos, 'views'),
    avg_views: round(sum(videos, 'views') / n, 0),
    avg_engagement_rate: round(sum(videos, 'engagement_rate') / n),
    avg_ctr_percent: round(sum(videos, 'ctr_percent') / n)
  },
  by_topic: group('topic'),
  by_category: group('category'),
  videos
};

return [{ json: { stats, stats_json: JSON.stringify(stats, null, 1) } }];

const out = $input.first().json.output;
const s = $('Calculate Metrics').first().json.stats;
const now = $now;

const lines = (arr, fn) => (arr || []).map(x => '• ' + fn(x)).join('\n');

return [{
  json: {
    'Report ID': `RPT-${now.toFormat('yyyyMMdd-HHmm')}`,
    'Date': now.toFormat('yyyy-MM-dd'),
    'Data Type': 'Simulated',
    'Videos Analyzed': s.overall.videos_analyzed,
    'Total Views': s.overall.total_views,
    'Avg Engagement Rate': s.overall.avg_engagement_rate + '%',
    'Overall Summary': out.overall_summary + ' ' + (out.data_note || ''),
    'Higher Engagement Topics': lines(out.higher_engagement_topics, t => `${t.topic}: ${t.evidence}`),
    'Lower Engagement Topics': lines(out.lower_engagement_topics, t => `${t.topic}: ${t.evidence}`),
    'Video Summaries': lines(out.video_summaries, v => `${v.video_id}: ${v.summary}`),
    'Suggested Topics': lines(out.suggested_topics, t => `${t.title} (${t.reason}; ${t.evidence})`),
    'Improvements': lines(out.improvements, i => `${i.area}: ${i.suggestion} (${i.evidence})`),
    'Status': 'Needs Review'
  }
}];

